var map;function init(locations){if(!locations&&typeof json_location!=='undefined'){locations=json_location}
const map=new google.maps.Map(document.getElementById('map-canvas'),{zoom:4});const styles=[{stylers:[{saturation:-100}]},{featureType:"landscape",stylers:[{visibility:"off"}]},{featureType:"poi",stylers:[{visibility:"off"}]},{featureType:"road",stylers:[{visibility:"on"}]},{stylers:[{lightness:20}]}];const styledMapType=new google.maps.StyledMapType(styles,{name:'Styled Map'});map.mapTypes.set('styled_maps',styledMapType);map.setMapTypeId('styled_maps');if(!Array.isArray(locations)||locations.length===0){return}
const bounds=new google.maps.LatLngBounds();locations.forEach(function(item){if(!item||!item.id)return;const parts=item.id.split(',');if(parts.length!==2)return;const lat=parseFloat(parts[0]);const lng=parseFloat(parts[1]);if(isNaN(lat)||isNaN(lng))return;const position=new google.maps.LatLng(lat,lng);bounds.extend(position);const marker=new google.maps.Marker({position:position,map:map,zIndex:9000});const infowindow=new InfoBox({shadowStyle:1,padding:5,borderRadius:4,arrowSize:10,borderWidth:1,disableAutoPan:!1,hideCloseButton:!0,arrowPosition:30,boxStyle:'infoBox',arrowStyle:2,zIndex:1000,infoBoxClearance:new google.maps.Size(1,1)});const description=item.description||'';const image_src=item.image||'';const imageHtml=image_src?'<img src="'+image_src+'" alt="" />':'';google.maps.event.addListener(marker,'click',function(){infowindow.setContent('<div class="mapInfo">'+imageHtml+(imageHtml?'<br>':'')+description+'</div>');infowindow.open(map,marker)})});map.fitBounds(bounds);google.maps.event.addListenerOnce(map,'bounds_changed',function(){if(locations.length===1){map.setZoom(12)}})}
if(typeof json_location=='object'){google.maps.event.addDomListener(window,'load',init(json_location))}